from bank import Q, M, TF, R

def D(ch, q, src, note="", ctx=None, img=None):
    """Drawing question: no model answer."""
    Q.append(dict(t="draw", ch=ch, q=q, s=src, p="drawing", e=note, img=img, ctx=ctx))

# ---------------------------------------------------------------- Midterm 1, 2nd semester 2026
M(1, "Which of the following is a primary benefit of using a database system?",
  ["Improved data consistency", "Increased data redundancy", "Program-data dependence", "None of the above"], 0, ["M26"], "slides",
  "A DBMS controls redundancy, which keeps data consistent. Redundancy and program-data dependence are file-system problems.")
M(1, "Who is responsible for managing the database system?",
  ["End users", "Database administrator (DBA)", "System Analyst", "None of the above"], 1, ["M26"], "slides",
  "Chapter 1: the DBA authorizes access, coordinates and monitors use of the database.")
M(1, "Which of the following best describes end users?",
  ["They design the database schema", "They manage security policies", "They use the database for queries and update", "None of the above"], 2, ["M26"], "slides",
  "Chapter 1, slide 26: 'End-users: they use the data for queries, reports and some of them actually update the database content.'")
M(2, "The database schema refers to:",
  ["The actual data stored at a given time", "Backup copies of the database", "The structure and definition of database", "None of the above"], 2, ["M26"], "slides",
  "The actual data at a given time is the database state (instance), not the schema.")
R(2, "Write the difference between database schema and database state.",
  "<b>Database schema:</b> the description of the database: its structure, data types and constraints. It is specified during design and rarely changes (also called the intension).<br><b>Database state:</b> the actual data stored in the database at a particular moment in time (also called an instance or snapshot, the extension). It changes every time data is inserted, deleted or updated.",
  ["M26"], "slides", "Chapter 2, 'Schemas, Instances, and Database State' slides.")
R(2, "Define the term data independence and explain the two levels of data independence in brief.",
  "<b>Data independence:</b> the capacity to change the schema at one level of the three-schema architecture without having to change the schema at the next higher level.<br><b>Logical data independence:</b> the capacity to change the conceptual schema without having to change the external schemas and their application programs.<br><b>Physical data independence:</b> the capacity to change the internal schema without having to change the conceptual schema.",
  ["M26"], "slides", "Chapter 2, slide 15.")
D(2, "Draw the three-schema architecture and show how its levels are connected to the stored database.", ["M26"],
  "Check your drawing against the Chapter 2 slides on the three-schema architecture.")
D(3, "Draw the ER diagram for this university database:<ul><li>A teacher has Teacher code (unique), Teacher's name consisting of (First name, Middle name and Family name), Teacher's address, rank, department.</li><li>The teacher teaches courses. Each course has course name, course number (unique), course credit hours.</li><li>Students register courses. Each student has student number (unique), name, major, date of birth, email (may have one or more emails).</li><li>Courses have sections. Each section has a number (unique) and location.</li><li>Dependencies:<ul><li>A teacher should teach at most 4 courses, and each course could be taught by two teachers.</li><li>A student may register many courses, and each course can be registered by many students.</li><li>The same course may have more than one section.</li></ul></li></ul>", ["M26"])

# ---------------------------------------------------------------- Drawing questions from earlier exams
D(4, "Draw the ER/EER diagram for the following Restaurant database requirements. Clearly indicate the entity types, attributes, relationship types, keys, and cardinalities.<ul><li>A customer must register his name, ID and contact number when entering the restaurant.</li><li>In the restaurant there are 3 types of employees (Cashier, Waiter, Chef); all of them have an ID and Name.</li><li>The waiter takes the customer order that contains order number, item descriptions, and price. A customer can have several orders.</li><li>The chef prepares the customers' orders.</li><li>When the customer finishes, he pays the bill that indicates the bill number and the order details to the cashier.</li></ul>",
  ["M23S"], "Marking scheme printed in the exam: 7 entities (0.25 each), 5 relationships (0.25 each), attributes 1, specialization 1, cardinality 1, participation (total/partial) 1; minus 0.25 for each mistake.")
D(4, "Draw the EER diagram for the following requirements. Clearly indicate the entity types, attributes, relationship types, keys, participation and relationship constraints (min, max).<br>A library wants to maintain a database of its members:<ul><li>Every member has an Id, a name, a date of birth and age.</li><li>Every member should be either a visitor, or a librarian who has, in addition to the member's attributes, a salary.</li><li>Each visitor may request at most eight book borrowing requests.</li><li>A borrow request has a request number which is identified uniquely for the visitor it is attached to; it also includes the borrow date.</li><li>Each borrow request should be provided by only one librarian, and each librarian may provide many borrow requests.</li></ul>",
  ["M24_2"])
D(4, "Draw the EER diagram for the following requirements. Clearly indicate the entity types, attributes, relationship types, keys, participation and relationship constraints (min, max).<br>A bank wants to maintain a database of its members:<ul><li>Every member has an Id, a name, a date of birth and age.</li><li>Every member should be either a client, or a bank teller who has, in addition to the member's attributes, a salary.</li><li>Each client may request at most four loan requests.</li><li>A loan request has a request number which is identified uniquely for the client it is attached to; it also includes the loan amount.</li><li>Each loan should be provided by only one bank teller, and each bank teller may provide many loan requests.</li></ul>",
  ["M23_1"])
D(3, "Many bookstore companies have launched several branches in the university, and the university wants a database to keep track of its products and recent purchases. Draw a complete ER diagram (without forgetting the cardinality ratio and total participation constraints):<ul><li>The bookstore has a unique ID and Name, and may have several branches.</li><li>Each branch has a location and a branch number that is unique only for the same bookstore. Each branch must belong to one bookstore at most.</li><li>Many branches may offer many books to sell, where each book has a unique ISBN, a title and a price. Each book must be offered by at least one branch.</li><li>These books can be bought or borrowed by customers. Customers can buy many books, but one customer can borrow one book at a time.</li><li>The customer must buy at least one book and can buy many at a time.</li><li>When a customer borrows a book, the borrowing date is registered automatically in the system.</li><li>The customer has a unique ID, Name and address as (city, street).</li></ul>",
  ["Q21"])
D(4, "Draw the EER diagram for the following requirements. Clearly indicate the entity types, attributes, relationship types, keys, participation and relationship constraints (min, max).<br>The National Football League (NFL) wants to maintain a database of its teams:<ul><li>Every team has a unique number, name, a city, a coach, a captain, and a set of players.</li><li>Each player has an ID, name, a skill level, and a position.</li><li>Each player must belong to exactly one team, and every team must have a minimum of 11 players and a maximum of 15 players.</li><li>Each team must have a captain who is also one of the players on the team.</li><li>Each match has a match number and date. Each match includes two teams that compete against each other. For each match, the score of each team (goals number) is stored in the database.</li><li>Every player may have one or more injury records, which include details such as the injury date and injury type. These injury records are uniquely tied to the player and cannot exist without the player. Each injury record is uniquely identified by player ID and injury date.</li></ul>",
  ["M24_1"])
D(4, "Draw the EER diagram for the following requirements. Clearly indicate the entity types, attributes, relationship types, keys, participation and relationship constraints (min, max).<br>The Motor Vehicle Branch administers driving tests and issues driver's licenses. Any person who wants a driver's license must take a learner's exam at any Motor Vehicle Branch in the province. If he/she fails the exam, he can take the exam again any time after a week of the failed exam date, at any branch. If he passes the exam, he is issued a license (type = learner's) with a unique license number. A learner's license may contain a single restriction on it. The person may take his driver's exam at any branch any time before the learner's license expiry date (which is usually set at six months after the license issue date). If he passes the exam, the branch issues him a driver's license. A driver's license must also record if the driver has completed driver's education, for insurance purposes.",
  ["M25_2"])
D(4, "Draw the EER diagram for the following requirements. Clearly indicate the entity types, attributes, relationship types, keys, participation and relationship constraints (min, max).<ul><li>The university keeps track of each student's name, student number, Social Security number, address and phone number, birth date, sex, major department, minor department (if any), and degree program (B.A., B.S., ..., Ph.D.). Both Social Security number and student number have unique values for each student.</li><li>Each staff member has a name, a Social Security number that has unique values, address, phone, birth date, sex, the courses he/she can teach, his/her college, his/her department and certification(s).</li><li>It is needed to keep track of each course actually taught by a specific staff member in a specific semester, with actual teaching hours and the count of registered students.</li><li>Each college has a name, college code, office phone numbers, a dean and a set of departments. Both college name and college code have unique values.</li><li>Each department is described by a name, department code, office number, office phone number, a manager (from the staff) and college. Both name and code have unique values for each department.</li><li>Each scheduled course has a course name, description, course number, scheduled number of hours, level, and offering department. The value of the course number is unique for each course.</li><li>Each section has an instructor, semester, year, course, and section number. The section number distinguishes sections of the same course that are taught during the same semester/year; its values are 1, 2, 3, ..., up to the number of sections taught during each semester.</li></ul>",
  ["M25_3"])

