R(8, "Write the SQL CREATE TABLE statement for the Student relation, making sure to enforce the primary and foreign key constraints.",
  "<pre>CREATE TABLE Student (\n  Name           varchar(20) NOT NULL,\n  Student_Number varchar(20),\n  Class          integer,\n  Major          varchar(10),\n  PRIMARY KEY (Student_Number),\n  FOREIGN KEY (Major) REFERENCES Course(Department)\n);</pre>",
  ["M21_2"], "key", "This is the official model answer. Strictly, a foreign key must reference a primary or unique key, and COURSE.Department is neither, so a real DBMS would reject that FOREIGN KEY line unless Department were declared UNIQUE.", ctx=uni_ctx)
